package com.node_modules.cofeshop;

import javafx.beans.property.SimpleBooleanProperty;
import javafx.beans.property.SimpleDoubleProperty;
import javafx.beans.property.SimpleIntegerProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.fxml.FXML;
import javafx.fxml.Initializable;
import javafx.scene.control.*;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.control.cell.PropertyValueFactory;
import javafx.scene.layout.AnchorPane;

import java.net.URL;
import java.text.NumberFormat;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.ResourceBundle;

/**
 * Controller class for the Admin interface
 * Handles dashboard, product management, and order processing
 */
public class AdminController implements Initializable {
    // Navigation buttons
    @FXML private Button dashboardBtn;
    @FXML private Button productBtn;
    @FXML private Button orderBtn;
    
    // Content panes
    @FXML private AnchorPane dashboardPane;
    @FXML private AnchorPane productPane;
    @FXML private AnchorPane orderPane;
    
    // Dashboard labels
    @FXML private Label totalPembelianLabel;
    @FXML private Label totalPenjualanLabel;
    @FXML private Label stockTersediaLabel;
    @FXML private Label stockTidakTersediaLabel;
    
    // Product table elements
    @FXML private TableView<Product> productTable;
    @FXML private TableColumn<Product, Integer> productIdColumn;
    @FXML private TableColumn<Product, String> productNameColumn;
    @FXML private TableColumn<Product, Double> productPriceColumn;
    @FXML private TableColumn<Product, Integer> productStockColumn;
    @FXML private TableColumn<Product, Void> productActionColumn;
    
    // Order table elements
    @FXML private TableView<OrderItem> orderItemTable;
    @FXML private TableColumn<OrderItem, String> itemNameColumn;
    @FXML private TableColumn<OrderItem, Integer> qtyColumn;
    @FXML private TableColumn<OrderItem, Double> priceColumn;
    
    // Order details elements
    @FXML private Label resNumberLabel;
    @FXML private Label totalPriceLabel;
    @FXML private TextField amountField;
    @FXML private ComboBox<String> paymentMethodCombo;
    @FXML private Label potonganLabel;
    @FXML private Label kembalianLabel;
    
    // Order action buttons
    @FXML private Button cancelBtn;
    @FXML private Button konfirmasiBtn;
    @FXML private Button addItemBtn;
    @FXML private Button removeItemBtn;
    
    // Data models
    private final ObservableList<Product> products = FXCollections.observableArrayList();
    private final ObservableList<OrderItem> orderItems = FXCollections.observableArrayList();
    
    // Payment properties
    private final SimpleBooleanProperty isQrisPayment = new SimpleBooleanProperty(true);
    private final SimpleBooleanProperty isTransferred = new SimpleBooleanProperty(false);
    private final SimpleDoubleProperty totalPrice = new SimpleDoubleProperty(0);
    private final NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(new Locale("id", "ID"));
    
    @Override
    public void initialize(URL url, ResourceBundle resourceBundle) {
        initNavigationButtons();
        setupDashboard();
        setupProductTable();
        setupOrderTable();
        setupReceiptArea();
        setupPaymentMethod();
        setupAmountField();
        setupOrderButtons();
        
        // Make sure only dashboard is visible initially
        showPane(dashboardPane);
    }
    
    /**
     * Initialize navigation buttons
     */
    private void initNavigationButtons() {
        dashboardBtn.setOnAction(e -> showPane(dashboardPane));
        productBtn.setOnAction(e -> showPane(productPane));
        orderBtn.setOnAction(e -> showPane(orderPane));
    }
    
    /**
     * Show selected pane and hide others
     * @param pane The pane to show
     */
    private void showPane(AnchorPane pane) {
        // Hide all panes first
        dashboardPane.setVisible(false);
        productPane.setVisible(false);
        orderPane.setVisible(false);
        
        // Show the selected pane
        pane.setVisible(true);
        
        // Update current button styling if needed
        updateButtonStyles(pane);
    }
    
    /**
     * Update button styles to show which section is active
     * @param activePane The currently active pane
     */
    private void updateButtonStyles(AnchorPane activePane) {
        // Reset all buttons to default style
        dashboardBtn.getStyleClass().remove("active-nav-button");
        productBtn.getStyleClass().remove("active-nav-button");
        orderBtn.getStyleClass().remove("active-nav-button");
        
        // Add active style to current button
        if (activePane == dashboardPane) {
            dashboardBtn.getStyleClass().add("active-nav-button");
        } else if (activePane == productPane) {
            productBtn.getStyleClass().add("active-nav-button");
        } else if (activePane == orderPane) {
            orderBtn.getStyleClass().add("active-nav-button");
        }
    }

    /**
     * Setup dashboard with sample data
     */
    private void setupDashboard() {
        totalPembelianLabel.setText(formatCurrency(5000000));
        totalPenjualanLabel.setText(formatCurrency(7500000));
        stockTersediaLabel.setText("150");
        stockTidakTersediaLabel.setText("25");
    }
    
    /**
     * Setup product table with sample data and formatters
     */
    private void setupProductTable() {
        try {
            // Clear any existing data first
            products.clear();
            
            // Add sample data
            products.addAll(
                new Product(1, "Laptop Asus ROG", 15000000.0, 5),
                new Product(2, "Monitor LG 24\"", 2500000.0, 10),
                new Product(3, "Mouse Logitech", 350000.0, 20),
                new Product(4, "Keyboard Mechanical", 850000.0, 15),
                new Product(5, "Headset Gaming", 750000.0, 8)
            );
            
            // Setup column value factories
            productIdColumn.setCellValueFactory(new PropertyValueFactory<>("id"));
            productNameColumn.setCellValueFactory(new PropertyValueFactory<>("name"));
            productPriceColumn.setCellValueFactory(new PropertyValueFactory<>("price"));
            productStockColumn.setCellValueFactory(new PropertyValueFactory<>("stock"));
            
            // Format price column with currency
            productPriceColumn.setCellFactory(column -> new javafx.scene.control.TableCell<Product, Double>() {
                @Override
                protected void updateItem(Double price, boolean empty) {
                    super.updateItem(price, empty);
                    if (empty || price == null) {
                        setText(null);
                    } else {
                        setText(currencyFormat.format(price));
                    }
                }
            });
            
            // Set the data items to the table and refresh
            productTable.setItems(products);
            productTable.refresh();
            
            // Update stock counts on dashboard
            updateStockCounts();
        } catch (Exception e) {
            e.printStackTrace();
            showErrorAlert("Error", "Table Setup Error", "Error setting up product table: " + e.getMessage());
        }
    }
    
    /**
     * Update stock counts on dashboard based on product data
     */
    private void updateStockCounts() {
        int inStock = 0;
        int outOfStock = 0;
        
        for (Product product : products) {
            if (product.getStock() > 0) {
                inStock++;
            } else {
                outOfStock++;
            }
        }
        
        stockTersediaLabel.setText(String.valueOf(inStock));
        stockTidakTersediaLabel.setText(String.valueOf(outOfStock));
    }
    
    /**
     * Setup order table with sample items and formatters
     */
    private void setupOrderTable() {
        try {
            // Clear any existing data first
            orderItems.clear();
            
            // Add sample data
            orderItems.addAll(
                new OrderItem("Laptop Asus ROG", 1, 15000000.0),
                new OrderItem("Mouse Logitech", 2, 350000.0)
            );
            
            // Setup column value factories
            itemNameColumn.setCellValueFactory(new PropertyValueFactory<>("name"));
            qtyColumn.setCellValueFactory(new PropertyValueFactory<>("quantity"));
            priceColumn.setCellValueFactory(new PropertyValueFactory<>("price"));
            
            // Format price column with currency
            priceColumn.setCellFactory(column -> new javafx.scene.control.TableCell<OrderItem, Double>() {
                @Override
                protected void updateItem(Double price, boolean empty) {
                    super.updateItem(price, empty);
                    if (empty || price == null) {
                        setText(null);
                    } else {
                        setText(currencyFormat.format(price));
                    }
                }
            });
            
            // Set the data items to the table and refresh
            orderItemTable.setItems(orderItems);
            orderItemTable.refresh();
            
            // Calculate initial total price
            calculateTotalPrice();
        } catch (Exception e) {
            e.printStackTrace();
            showErrorAlert("Error", "Table Setup Error", "Error setting up order table: " + e.getMessage());
        }
    }

    /**
     * Format a numeric value as Indonesian currency
     * @param amount The amount to format
     * @return Formatted currency string
     */
    private String formatCurrency(double amount) {
        NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(new Locale("id", "ID"));
        return currencyFormat.format(amount).replace("Rp", "Rp.");
    }
    
    /**
     * Setup receipt area with date and order number
     */
    private void setupReceiptArea() {
        // Generate receipt number with date
        LocalDate today = LocalDate.now();
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd MMM yyyy");
        String resNumber = "Res/18743/" + today.format(formatter);
        resNumberLabel.setText(resNumber);
        
        // Bind total price to label
        totalPriceLabel.textProperty().bind(totalPrice.asString("Rp. %.0f"));
    
        // Set discount percentage
        potonganLabel.setText("2%");
    }
    
    /**
     * Setup payment method combo box and related behaviors
     */
    private void setupPaymentMethod() {
        // Initialize with QRIS
        paymentMethodCombo.getItems().addAll("Qris", "Cash");
        paymentMethodCombo.setValue("Qris");

        // Bind QRIS payment property to combo box value
        isQrisPayment.bind(paymentMethodCombo.valueProperty().isEqualTo("Qris"));
        
        // Listen for payment method changes
        paymentMethodCombo.valueProperty().addListener((obs, oldVal, newVal) -> {
            if ("Cash".equals(newVal)) {
                amountField.setDisable(false);
                amountField.setText("");
                amountField.setPromptText("Masukkan jumlah");
            } else {
                amountField.setDisable(true);
                amountField.setText(currencyFormat.format(totalPrice.get()));
                kembalianLabel.setText("0");
            }
            
            isTransferred.set(false);
            updateButtonStates();
        });
    }
    
    /**
     * Setup amount field listener to calculate change
     */
    private void setupAmountField() {
        amountField.textProperty().addListener((obs, oldVal, newVal) -> {
            if (!isQrisPayment.get()) {
                try {
                    // Parse input removing non-numeric characters
                    String cleanInput = newVal.replaceAll("[^\\d.]", "");
                    if (!cleanInput.isEmpty()) {
                        double amount = Double.parseDouble(cleanInput);
                        double change = amount - totalPrice.get();
                        
                        if (change >= 0) {
                            kembalianLabel.setText(currencyFormat.format(change));
                        } else {
                            kembalianLabel.setText("Kurang " + currencyFormat.format(Math.abs(change)));
                        }
                    } else {
                        kembalianLabel.setText("0");
                    }
                } catch (NumberFormatException e) {
                    kembalianLabel.setText("Format tidak valid");
                }
            }
        });
    }
    
    /**
     * Setup order-related buttons and their actions
     */
    private void setupOrderButtons() {
        // QRIS transfer simulation button
        Button transferQrisBtn = new Button("Simulasi Transfer QRIS");
        transferQrisBtn.setOnAction(e -> {
            isTransferred.set(true);
            updateButtonStates();
            showSuccessAlert("QRIS Payment", "Pembayaran QRIS Berhasil", 
                    "Pembayaran QRIS sebesar " + currencyFormat.format(totalPrice.get()) + " telah diterima.");
        });
        
        // Add QRIS button to order pane
        AnchorPane.setBottomAnchor(transferQrisBtn, 20.0);
        AnchorPane.setRightAnchor(transferQrisBtn, 20.0);
        orderPane.getChildren().add(transferQrisBtn);
        
        // Configure cancel button
        cancelBtn.setOnAction(e -> {
            if (canCancel()) {
                resetOrder();
            } else {
                showWarningAlert("Tidak dapat dibatalkan", "Order tidak dapat dibatalkan",
                        "Pembayaran QRIS telah dikonfirmasi dan tidak dapat dibatalkan.");
            }
        });
        
        // Configure confirm button
        konfirmasiBtn.setOnAction(e -> {
            if (validateOrder()) {
                processOrder();
            }
        });
        
        // Set initial button states
        updateButtonStates();
    }
    
    /**
     * Check if order can be canceled
     * @return true if cancelable, false otherwise
     */
    private boolean canCancel() {
        return !isQrisPayment.get() || !isTransferred.get();
    }
    
    /**
     * Update button states based on current payment state
     */
    private void updateButtonStates() {
        cancelBtn.setDisable(!canCancel());
    }
    
    /**
     * Validate order before processing
     * @return true if valid, false otherwise
     */
    private boolean validateOrder() {
        if (orderItems.isEmpty()) {
            showErrorAlert("Error", "Tidak ada item", "Silakan tambahkan item ke order.");
            return false;
        }
        
        if (!isQrisPayment.get()) {
            try {
                String amountText = amountField.getText().replaceAll("[^\\d.]", "");
                if (amountText.isEmpty()) {
                    showErrorAlert("Error", "Jumlah tidak valid", "Silakan masukkan jumlah pembayaran.");
                    return false;
                }
                
                double amount = Double.parseDouble(amountText);
                if (amount < totalPrice.get()) {
                    showErrorAlert("Error", "Jumlah kurang", "Pembayaran kurang dari total harga.");
                    return false;
                }
            } catch (NumberFormatException e) {
                showErrorAlert("Error", "Format tidak valid", "Format jumlah pembayaran tidak valid.");
                return false;
            }
        } else if (!isTransferred.get()) {
            showErrorAlert("Error", "QRIS belum ditransfer", "Silakan selesaikan transfer QRIS terlebih dahulu.");
            return false;
        }
        
        return true;
    }
    
    /**
     * Process the order after validation
     */
    private void processOrder() {
        showSuccessAlert("Order Berhasil", "Order telah dikonfirmasi",
                "Order telah berhasil diproses dengan pembayaran " + 
                (isQrisPayment.get() ? "QRIS" : "Cash") + ".");
        
        resetOrder();
    }
    
    /**
     * Reset order to initial state
     */
    private void resetOrder() {
        orderItems.clear();
        isTransferred.set(false);
        paymentMethodCombo.setValue("Qris");
        amountField.clear();
        kembalianLabel.setText("0");
        calculateTotalPrice();
        updateButtonStates();
    }
    
    /**
     * Calculate total price from all order items
     */
    private void calculateTotalPrice() {
        double sum = orderItems.stream()
                .mapToDouble(item -> item.getPrice() * item.getQuantity())
                .sum();
        totalPrice.set(sum);
    }
    
    /**
     * Show error alert with specified message
     */
    private void showErrorAlert(String title, String header, String content) {
        Alert alert = new Alert(Alert.AlertType.ERROR);
        alert.setTitle(title);
        alert.setHeaderText(header);
        alert.setContentText(content);
        alert.showAndWait();
    }
    
    /**
     * Show warning alert with specified message
     */
    private void showWarningAlert(String title, String header, String content) {
        Alert alert = new Alert(Alert.AlertType.WARNING);
        alert.setTitle(title);
        alert.setHeaderText(header);
        alert.setContentText(content);
        alert.showAndWait();
    }
    
    /**
     * Show success alert with specified message
     */
    private void showSuccessAlert(String title, String header, String content) {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle(title);
        alert.setHeaderText(header);
        alert.setContentText(content);
        alert.showAndWait();
    }
    
    /**
     * Product model class
     */
    public static class Product {
        private final SimpleIntegerProperty id;
        private final SimpleStringProperty name;
        private final SimpleDoubleProperty price;
        private final SimpleIntegerProperty stock;
        
        public Product(int id, String name, double price, int stock) {
            this.id = new SimpleIntegerProperty(id);
            this.name = new SimpleStringProperty(name);
            this.price = new SimpleDoubleProperty(price);
            this.stock = new SimpleIntegerProperty(stock);
        }
        
        public int getId() { return id.get(); }
        public String getName() { return name.get(); }
        public double getPrice() { return price.get(); }
        public int getStock() { return stock.get(); }
    }
    
    /**
     * Order item model class
     */
    public static class OrderItem {
        private final SimpleStringProperty name;
        private final SimpleIntegerProperty quantity;
        private final SimpleDoubleProperty price;
        
        public OrderItem(String name, int quantity, double price) {
            this.name = new SimpleStringProperty(name);
            this.quantity = new SimpleIntegerProperty(quantity);
            this.price = new SimpleDoubleProperty(price);
        }
        
        public String getName() { return name.get(); }
        public int getQuantity() { return quantity.get(); }
        public double getPrice() { return price.get(); }
    }
}